begin;

do $$ begin
  if not (exists (select 1 from information_schema.columns where table_name = 'ticket_types' and column_name = 'tier')) then
    raise exception 'Stopped before changing anything: apply migration 33 (supabase/manual/update-33) first.';
  end if;
