-- Migration 34: what a post needs before it can be published, enforced by the database (not only the composer).
--  * A post needs meaningful text or a photo/video. A song, feeling, place or tagged friends alone no longer qualify
--    (migration 15 had allowed them). Meaningful text = something left after removing spaces, invisible characters,
--    punctuation, symbols and emoji (so "   ", "…", "🔥🔥" or a zero-width space do not count; "Hi" does).
--  * posts.media_path must be the author's own upload and must exist in storage (a failed or unfinished upload cannot
--    publish a post, and nobody can attach another member's file). Gallery rows (post_media) get the same existence check.
--  * posts.client_key: one key per composer draft, unique per author, so a retried or double-sent publish returns the
--    same post instead of creating a second one.
-- Production was checked before writing this: no existing post breaks these rules, so the constraints are validated.
-- Rollback: drop posts_has_meaningful_content / posts_media_path_owner, the two triggers and the client_key index, and
-- restore migration 15's posts_has_content.

create or replace function public.meaningful_text(t text) returns boolean
language sql immutable set search_path = '' as $$
  select char_length(regexp_replace(coalesce(t, ''),
    '[[:space:][:punct:]\u00a0\u00ad\u034f\u061c\u115f\u1160\u17b4\u17b5\u180e\u200b-\u200f\u2028-\u202f\u205f-\u206f\u3000\u3164\ufe00-\ufe0f\ufeff\uffa0\u20e3\u2190-\u21ff\u2300-\u23ff\u2460-\u24ff\u25a0-\u27bf\u2900-\u297f\u2b00-\u2bff\U0001F000-\U0001FAFF\U000E0000-\U000E007F]',
    '', 'g')) > 0;
$$;

alter table public.posts drop constraint if exists posts_has_content;
alter table public.posts drop constraint if exists posts_has_meaningful_content;
alter table public.posts add constraint posts_has_meaningful_content check (public.meaningful_text(body) or media_path is not null);
alter table public.posts drop constraint if exists posts_media_path_owner;
alter table public.posts add constraint posts_media_path_owner check (media_path is null or (media_path like author::text || '/%' and media_type in ('image', 'video')));

-- An upload that never finished (or a made-up path) has no storage object: refuse it.
create or replace function public.media_uploaded(p text) returns boolean
language sql stable security definer set search_path = '' as $$
  select p is null or exists (select 1 from storage.objects o where o.bucket_id = 'media' and o.name = p);
$$;
create or replace function public.trg_post_media_uploaded() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.media_path is not distinct from old.media_path then return new; end if;
  if not public.media_uploaded(new.media_path) then raise exception 'The photo or video has not finished uploading' using errcode = '23514'; end if;
  return new;
end $$;
create or replace function public.trg_gallery_media_uploaded() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if not public.media_uploaded(new.path) then raise exception 'The photo or video has not finished uploading' using errcode = '23514'; end if;
  return new;
end $$;
drop trigger if exists posts_media_uploaded on public.posts;
create trigger posts_media_uploaded before insert or update of media_path on public.posts for each row execute function public.trg_post_media_uploaded();
drop trigger if exists post_media_uploaded on public.post_media;
create trigger post_media_uploaded before insert on public.post_media for each row execute function public.trg_gallery_media_uploaded();
revoke execute on function public.trg_post_media_uploaded(), public.trg_gallery_media_uploaded(), public.media_uploaded(text) from public, anon, authenticated;

alter table public.posts add column if not exists client_key uuid;
create unique index if not exists posts_author_client_key on public.posts (author, client_key) where client_key is not null;

commit;

select item, ok from (values
  ('a post needs meaningful text or a photo/video', exists (select 1 from pg_constraint where conname = 'posts_has_meaningful_content' and convalidated) and not exists (select 1 from pg_constraint where conname = 'posts_has_content') and not public.meaningful_text(' … 🔥 ') and public.meaningful_text('Hi')),
  ('a post only uses files its author uploaded', exists (select 1 from pg_constraint where conname = 'posts_media_path_owner' and convalidated)),
  ('unfinished uploads are refused', exists (select 1 from pg_trigger where tgname = 'posts_media_uploaded') and exists (select 1 from pg_trigger where tgname = 'post_media_uploaded') and not has_function_privilege('authenticated', 'public.media_uploaded(text)', 'execute')),
  ('a retried publish cannot duplicate', exists (select 1 from pg_indexes where indexname = 'posts_author_client_key')),
  ('no trigger function callable over the API', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prorettype = 'trigger'::regtype and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))))
) as v(item, ok);
-- END OF MIGRATION 34
